      const period   = sampleRate / this._frequency;
      this._phase    = (this._phase + 1) % period;
      const p    = this._phase;
      const duty = this._dutyCycle;
      const db   = this._deadBand;
      const amp  = this._amplitude;
      const highEnd  = duty * period;
